static const float RL_SB3_B3 = -0.0006202f;

/* Cấu trúc lưu trữ trạng thái lịch sử cho mạng nơ-ron */
typedef struct {
    float prev_theta;
    float prev_dtheta;
    float prev_x;
    float prev_v;
    float prev_action;
} RL_SB3_Controller_t;

static inline void RL_SB3_Init(RL_SB3_Controller_t *ctrl) {
    ctrl->prev_theta = 0.0f;
    ctrl->prev_dtheta = 0.0f;
    ctrl->prev_x = 0.0f;
    ctrl->prev_v = 0.0f;
    ctrl->prev_action = 0.0f;
}

/**
 * @brief Hàm suy luận nơ-ron thời gian thực trong chu kỳ ngắt 200 Hz (5 ms)
 * @param ctrl   Bộ điều khiển lưu lịch sử
 * @param theta  Góc nghiêng đo từ IMU (rad)
 * @param dtheta Vận tốc góc đo từ Gyro (rad/s)
 * @param x      Vị trí đo từ Encoder (m)
 * @param v      Vận tốc di chuyển (m/s)
 * @return float Xung PWM điều khiển động cơ [-999.0, +999.0]
 */
static inline float RL_SB3_Step(RL_SB3_Controller_t *ctrl, float theta, float dtheta, float x, float v) {
    float in_vec[9] = {
        theta, dtheta, x, v,
        ctrl->prev_theta, ctrl->prev_dtheta, ctrl->prev_x, ctrl->prev_v,
        ctrl->prev_action
    };

    /* Tầng ẩn 1: Linear + Tanh */
    float h1[64];
    for (int i = 0; i < 64; i++) {
        float sum = RL_SB3_B1[i];
        for (int j = 0; j < 9; j++) {
            sum += RL_SB3_W1[i][j] * in_vec[j];
        }
        h1[i] = tanhf(sum);
    }

    /* Tầng ẩn 2: Linear + Tanh */
    float h2[64];
    for (int i = 0; i < 64; i++) {
        float sum = RL_SB3_B2[i];
        for (int j = 0; j < 64; j++) {
            sum += RL_SB3_W2[i][j] * h1[j];
        }
        h2[i] = tanhf(sum);
    }

    /* Tầng đầu ra: Linear + Bão hòa [-1.0, +1.0] (Chuẩn SB3 continuous Box action) */
    float out = RL_SB3_B3;
    for (int j = 0; j < 64; j++) {
        out += RL_SB3_W3[j] * h2[j];
    }

    float action = out;
    if (action > 1.0f) action = 1.0f;
    else if (action < -1.0f) action = -1.0f;

    /* Lưu lại lịch sử cho chu kỳ kế tiếp */
    ctrl->prev_theta = theta;
    ctrl->prev_dtheta = dtheta;
    ctrl->prev_x = x;
    ctrl->prev_v = v;
    ctrl->prev_action = action;

    float pwm = action * 999.0f;
    if (pwm > 999.0f) pwm = 999.0f;
    else if (pwm < -999.0f) pwm = -999.0f;
    return pwm;
}

